import{_ as a,o as e,c as d,ag as r}from"./chunks/framework.DMXcdKmJ.js";const u=JSON.parse('{"title":"保留数据后重新安装","description":"在原服务器保留原数据卷后，使用完整原安装包重新安装中心，并用原账号验证访问。","frontmatter":{"title":"保留数据后重新安装","description":"在原服务器保留原数据卷后，使用完整原安装包重新安装中心，并用原账号验证访问。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/installation/reinstall.md","filePath":"zh/安装运维/保留数据后重新安装.md"}'),i={name:"zh/installation/reinstall.md"};function l(o,t,h,n,s,c){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="保留数据后重新安装" tabindex="-1">保留数据后重新安装 <a class="header-anchor" href="#保留数据后重新安装" aria-label="Permalink to &quot;保留数据后重新安装&quot;">​</a></h1><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>在成功完成保留数据卸载后，使用原安装包重新安装中心，重新连接原数据，并使用原管理员账号访问原组织。</p><blockquote><p>本页只适用于原服务器、原数据卷和同一安装包的重新安装。保留数据卸载不是备份，不是跨版本升级，也不能用来迁移服务器。重新登录原组织后，仍需分别核对原有业务数据和采集、计算、报警等业务功能。</p></blockquote><h2 id="角色与环境前提" tabindex="-1">角色与环境前提 <a class="header-anchor" href="#角色与环境前提" aria-label="Permalink to &quot;角色与环境前提&quot;">​</a></h2><p>由具备服务器系统管理权限的维护人员执行，并请平台管理员和组织管理员配合验证。</p><table tabindex="0"><thead><tr><th>必须保留的材料</th><th>要求</th></tr></thead><tbody><tr><td>原服务器</td><td>没有重装系统，原运行环境仍在</td></tr><tr><td>原数据卷</td><td>未删除、未替换，原磁盘仍正确连接；不能用同名空数据卷替代</td></tr><tr><td>原安装包</td><td>使用上次成功安装的完整原包，不改用其他版本</td></tr><tr><td>原账号</td><td>原平台超级管理员、原组织管理员的用户名和密码可用</td></tr><tr><td>原凭据与留存记录</td><td>由保留数据卸载留下的内容保持完整，不手工移动或删除</td></tr><tr><td>卸载结果</td><td>已明确完成保留数据卸载，没有清理失败或未完成的提示</td></tr></tbody></table><p>同时核对<a href="/induframe-docs/zh/installation/prepare.html">安装前准备</a>中的磁盘余量、网络和访问条件。任一材料缺失，或不能确认卸载结果时，先交给维护人员处理，不直接执行本页步骤。</p><h2 id="操作入口" tabindex="-1">操作入口 <a class="header-anchor" href="#操作入口" aria-label="Permalink to &quot;操作入口&quot;">​</a></h2><p>在<strong>原服务器</strong>的交互终端中，进入完整原安装包目录，执行包内的安装入口。</p><div class="language-sh vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./install.sh</span></span></code></pre></div><h2 id="重新安装步骤与字段" tabindex="-1">重新安装步骤与字段 <a class="header-anchor" href="#重新安装步骤与字段" aria-label="Permalink to &quot;重新安装步骤与字段&quot;">​</a></h2><h3 id="_1-核对保留状态" tabindex="-1">1. 核对保留状态 <a class="header-anchor" href="#_1-核对保留状态" aria-label="Permalink to &quot;1. 核对保留状态&quot;">​</a></h3><p>确认此前按<a href="/induframe-docs/zh/installation/uninstall.html">卸载平台</a>操作：第一次确认卸载回答 <code>y</code>，第二次删除数据询问回答 <code>n</code> 或直接回车，且卸载已明确成功结束。</p><p>不要把“取消卸载”误认为已完成保留数据卸载，也不要在卸载未完成时继续重装。</p><h3 id="_2-重新填写安装向导" tabindex="-1">2. 重新填写安装向导 <a class="header-anchor" href="#_2-重新填写安装向导" aria-label="Permalink to &quot;2. 重新填写安装向导&quot;">​</a></h3><p>保留数据卸载后，安装器会再次收集安装设置。按照<a href="/induframe-docs/zh/installation/install.html">安装中心</a>填写以下内容，并与原有交接记录核对。</p><table tabindex="0"><thead><tr><th>字段</th><th>重新安装时的处理</th></tr></thead><tbody><tr><td>存放位置</td><td>重新填写程序父目录，建议沿用原位置；默认 <code>/opt</code> 对应 <code>/opt/induframe</code></td></tr><tr><td>公共访问地址与端口</td><td>核对原有地址是否仍有效，默认公共端口 <code>443</code>，使用 HTTPS</td></tr><tr><td>管理入口端口</td><td>默认 <code>18100</code>，管理地址仍由安装器自动选择服务器内网地址</td></tr><tr><td>平台超级管理员用户名</td><td>按向导填写，并保留原有账号资料供登录验证</td></tr><tr><td>证书方式及文件</td><td>重新选择；自带证书需重新提供并核对所需文件</td></tr><tr><td>平台超级管理员初始密码</td><td>向导仍要求输入两次，符合 8–72 字节限制；已初始化平台继续使用原密码</td></tr></tbody></table><p><strong>此次填写的初始密码不会覆盖已有平台管理员。</strong> 向导中的新输入也不能用来找回或替换原账号；登录时使用原平台超级管理员的用户名和密码。原组织管理员同样使用原来的密码。</p><p>如果忘记原密码，先联系维护人员处理账号，不要通过反复重新安装尝试重置。</p><h3 id="_3-等待安装完成" tabindex="-1">3. 等待安装完成 <a class="header-anchor" href="#_3-等待安装完成" aria-label="Permalink to &quot;3. 等待安装完成&quot;">​</a></h3><p>安装器会核对保留记录与原数据是否一致，再连接原数据。若提示原数据缺失、发生替换、凭据缺失或卸载未完成，应停止操作并保留现场。</p><p>等待完整的 14 个阶段完成，安装命令正常结束、退出状态为 <code>0</code>，并显示“InduFrame 中心安装完成。”。保存本次打印的公共入口、管理入口和安装日志路径。</p><h3 id="_4-重新核对证书信任" tabindex="-1">4. 重新核对证书信任 <a class="header-anchor" href="#_4-重新核对证书信任" aria-label="Permalink to &quot;4. 重新核对证书信任&quot;">​</a></h3><p>选择自签名证书时，本次重新安装会生成新证书。浏览器可能再次提示证书不受信任；请维护人员核对新的证书与访问地址，重新处理信任后再登录。不要因为地址相同就直接沿用对旧证书的判断。</p><h3 id="_5-使用原账号验证" tabindex="-1">5. 使用原账号验证 <a class="header-anchor" href="#_5-使用原账号验证" aria-label="Permalink to &quot;5. 使用原账号验证&quot;">​</a></h3><ol><li>打开本次安装结果给出的管理入口，使用<strong>原平台超级管理员</strong>登录，确认原组织仍在。</li><li>打开公共入口“登录工作台”，出现“选择组织”时选择原组织；只有一个可登录组织时自动选中。</li><li>使用<strong>原组织管理员</strong>用户名和密码登录。</li><li>按<a href="/induframe-docs/zh/installation/verify.html">确认安装成功</a>检查工程管理、页面刷新和退出。</li><li>请业务负责人另外核对所需工程、数据及业务功能，再恢复日常使用。</li></ol><p>原组织已经完成首次设置时，不需要再重置默认组织管理员密码。</p><h2 id="成功确认" tabindex="-1">成功确认 <a class="header-anchor" href="#成功确认" aria-label="Permalink to &quot;成功确认&quot;">​</a></h2><ul><li>本次安装满足 14 个阶段完成、正常退出和“InduFrame 中心安装完成。”三项条件。</li><li>原平台管理员可以查看原组织，原组织管理员可以用原密码登录。</li><li>基本页面访问、刷新和退出正常，业务负责人已知晓仍需核对的业务范围。</li></ul><p>可登录原组织不等于已验证全部业务恢复，也不能代替备份恢复检查。</p><h2 id="未能完成时" tabindex="-1">未能完成时 <a class="header-anchor" href="#未能完成时" aria-label="Permalink to &quot;未能完成时&quot;">​</a></h2><p>记录安装阶段、提示和日志路径，保留原服务器、数据、凭据及留存记录，联系维护人员。不要删除记录来跳过校验，不要创建同名空数据卷，也不要改用删除数据卸载来消除提示。</p><p>中断或失败后的继续处理需要根据现场确认，本页不提供反复重跑即可修复的操作保证。先查信息见<a href="/induframe-docs/zh/installation/troubleshooting.html">安装常见问题</a>。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>基本访问确认完成后，交给业务负责人继续检查实际工程和运行状态。日常使用入口见<a href="/induframe-docs/zh/guide/login.html">登录与退出</a>；需要再次停用时，重新核对<a href="/induframe-docs/zh/installation/uninstall.html">卸载平台</a>中的影响范围。</p>',36)])])}const b=a(i,[["render",l]]);export{u as __pageData,b as default};
